// Получаем данные закупки от CRM
const data = $input.first().json.body || $input.first().json;

const publicationId = data.publication_id;
const purchase = data;

// Формируем данные для Фабрикант API
// TODO: заполнить после получения WSDL-схем от Фабрикант
const fabrikantPayload = {
  // Основные поля лота
  lotName: purchase.subject || 'Закупка #' + purchase.purchase_id,
  lotDescription: purchase.items?.map(i => `${i.item_name} — ${i.quantity} ${i.unit}`).join('\n') || '',
  startPrice: purchase.nmck,
  currency: 'RUB',

  // Сроки
  deliveryTerm: purchase.execution_term,

  // Организация (заполнить реквизиты)
  organizationInn: purchase.contractor?.inn || 'УКАЖИТЕ_ИНН',
  organizationOgrn: purchase.contractor?.ogrn || 'УКАЖИТЕ_ОГРН',

  // Позиции
  items: (purchase.items || []).map(item => ({
    name: item.item_name,
    quantity: item.quantity,
    unit: item.unit,
    unitPrice: item.unit_price,
  })),

  // Служебные
  _publicationId: publicationId,
  _purchaseId: purchase.purchase_id,
};

return [{ json: { publicationId, fabrikantPayload, rawData: purchase } }];

const { publicationId, fabrikantPayload } = $input.first().json;
const testMode = ($env.FABRIKANT_TEST_MODE || '') === 'true';

if (testMode) {
  return [{ json: {
    publicationId,
    success: true,
    externalId: 'TEST-FAB-' + Date.now(),
    externalUrl: 'https://fabrikant.ru/test-lot',
  }}];
}

// Без test mode — возвращаем ошибку с инструкцией (реальная SOAP интеграция не реализована)
return [{ json: {
  publicationId,
  success: false,
  error: 'API Фабрикант не настроен. Получите SOAP credentials на fabrikant.ru/integration-api и настройте переменные FABRIKANT_LOGIN, FABRIKANT_PASSWORD в n8n Settings → Variables. Включите тестовый режим: FABRIKANT_TEST_MODE=true',
}}];
